INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gap-in-the-trees', 'west', 'the-eaves', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-eaves', 'door', 'The Eaves', 'The wood does not start gradually. One step the light is grey and open and the track is under you, the next the trunks have closed over and it has gone green and close and the air is ten degrees colder. Behind you the gap still shows the road. Ahead there is no gap at all.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eaves', 'east', 'the-gap-in-the-trees', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eaves', 'west', 'the-deer-path', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eaves', 'north', 'the-birch-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eaves', 'south', 'the-bramble-margin', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-birch-edge', 'door', 'The Birch Edge', 'Birch grows in the poor ground along the wood''s margin, thin and white and close-ranked, all of it leaning the same way from a wind that does not reach in this far any more. You can still see daylight through it if you look back east.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-birch-edge', 'south', 'the-eaves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-birch-edge', 'west', 'the-holly-brake', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-bramble-margin', 'door', 'The Bramble Margin', 'Bramble has taken the whole southern edge, chest-high and grown through itself in loops, and there is one way through it that was not cut by anything with hands. It closes behind you at about knee height.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bramble-margin', 'north', 'the-eaves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bramble-margin', 'west', 'the-nettle-glade', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-deer-path', 'door', 'The Deer Path', 'A narrow line of bare earth winds west between the trunks, packed hard and no wider than a shoulder. Nothing made it on purpose. It goes where the deer needed to go, which is not necessarily anywhere you need to be.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-path', 'east', 'the-eaves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-path', 'west', 'the-first-clearing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-path', 'north', 'the-holly-brake', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-path', 'south', 'the-nettle-glade', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-holly-brake', 'door', 'The Holly Brake', 'Holly grows dense enough here to stop the light entirely, dark green and waxed and armed on every leaf. Underneath there is bare ground and a dry rustling carpet of old spines, and nothing else grows in it at all.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-brake', 'east', 'the-birch-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-brake', 'south', 'the-deer-path', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-brake', 'west', 'the-pollard-row', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-nettle-glade', 'door', 'The Nettle Glade', 'A break in the canopy has let enough light down for nettles, and they have taken every inch of it, waist-high and unbroken. Something has been through recently — there is a green wound of crushed stems, already lifting back upright.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nettle-glade', 'east', 'the-bramble-margin', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nettle-glade', 'north', 'the-deer-path', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-nettle-glade', 'west', 'the-wet-hollow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-first-clearing', 'door', 'The First Clearing', 'Open ground, a good bowshot across, ringed by trees standing shoulder to shoulder as if they had agreed on the edge. Grass, not leaf-mould. Nothing has grown back into it in a long time, and something is keeping it that way.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-clearing', 'east', 'the-deer-path', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-clearing', 'west', 'the-fallen-giant', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-clearing', 'north', 'the-pollard-row', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-clearing', 'south', 'the-wet-hollow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-pollard-row', 'door', 'The Pollard Row', 'A line of trees cut off at head height, long ago and repeatedly, so each one has thrown up a fist of thick vertical growth from the same scarred knuckle. They run north to south in a dead straight line. Somebody managed this wood once, on a schedule.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pollard-row', 'east', 'the-holly-brake', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pollard-row', 'south', 'the-first-clearing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pollard-row', 'west', 'the-lightning-split', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pollard-row', 'north', 'the-stone-pile', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-stone-pile', 'door', 'The Stone Pile', 'A cairn of field stones the height of a man, thick with moss on every face but the south. It is not a grave and not a wall and not a marker for anything you can see. It is where a great many stones were carried, one at a time, by people who wanted them out of somewhere else.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-pile', 'south', 'the-pollard-row', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-wet-hollow', 'door', 'The Wet Hollow', 'The ground dishes and holds water here, and alder has come in around a black standing pool no bigger than a room. Everything smells of iron and rot. The leaf-litter under the surface goes down further than you would think.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-hollow', 'east', 'the-nettle-glade', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-hollow', 'north', 'the-first-clearing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-hollow', 'west', 'the-badger-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-hollow', 'south', 'the-drinking-pool', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-drinking-pool', 'door', 'The Drinking Pool', 'A wider water in a ring of trodden mud, and the mud is printed all over — deer, and something with pads, and something bigger than both that came down to the water alone. The water itself is clear, and cold, and moving very slightly from somewhere underneath.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drinking-pool', 'north', 'the-wet-hollow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-fallen-giant', 'door', 'The Fallen Giant', 'An oak came down here a generation ago and took three others with it, and the whole tangle lies where it fell, going back to earth on its own schedule. The root-plate stands on end, taller than you, with a crater of dark soil where it tore out.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-giant', 'east', 'the-first-clearing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-giant', 'west', 'the-boundary-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-giant', 'north', 'the-lightning-split', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-giant', 'south', 'the-badger-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-lightning-split', 'door', 'The Lightning Split', 'A beech split top to bottom by something that came down out of the sky, its two halves leaning apart and still living, the wound between them gone black and hard. It happened long enough ago that ivy has dressed it.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lightning-split', 'east', 'the-pollard-row', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lightning-split', 'south', 'the-fallen-giant', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lightning-split', 'west', 'the-ash-stand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-badger-ground', 'door', 'The Badger Ground', 'The bank here is worked all over with holes and spoil-heaps of pale earth, generations of them, most collapsed and a few very much not. There are paths between them worn to the width of a low, heavy animal.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-badger-ground', 'east', 'the-wet-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-badger-ground', 'north', 'the-fallen-giant', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-badger-ground', 'west', 'the-charcoal-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-boundary-oak', 'door', 'The Boundary Oak', 'An oak far older than anything around it, hollow, and wide enough that four people could stand inside the trunk. Ancient iron is grown deep into the bark on the eastern face — the remains of a plate, or a hinge, or a nail somebody drove for a reason nobody kept.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-oak', 'east', 'the-fallen-giant', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-oak', 'west', 'the-turning', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-oak', 'north', 'the-ash-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-oak', 'south', 'the-charcoal-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-ash-stand', 'door', 'The Ash Stand', 'Ash grown up all of a height from a single felling, the whole stand the same age and the same thickness, the trunks running up straight and grey to a canopy that starts well above your head. Between them you can see a long way and none of it is different.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-stand', 'east', 'the-lightning-split', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-stand', 'south', 'the-boundary-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ash-stand', 'west', 'the-close-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-charcoal-flat', 'door', 'The Charcoal Flat', 'A level circle of ground where the earth is black to a depth of a foot, and nothing has grown on it since. They stacked and burned wood here for weeks at a time. Around the edge, the ground is heaped where the turf was cut away and never put back.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-charcoal-flat', 'east', 'the-badger-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-charcoal-flat', 'north', 'the-boundary-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-charcoal-flat', 'west', 'the-swallowing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-charcoal-flat', 'south', 'the-charcoal-hut', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-charcoal-hut', 'door', 'The Charcoal Hut', 'A shelter of poles and turf, half sunk into the ground, built for one man to sleep in with one eye open while his stack burned. The roof holds. Nothing dens here — it smells too strongly of old fire, and everything with a nose knows what that means.', 0, 1, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-charcoal-hut', 'north', 'the-charcoal-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-turning', 'door', 'The Turning', 'The trees stand closer together west of here, and the ground begins to lift and fold in a way that means nothing in particular. There is no marker, no gate, no change in the light worth reporting. It is simply the last place in this wood where going back the way you came works.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turning', 'east', 'the-boundary-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turning', 'north', 'the-close-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turning', 'south', 'the-swallowing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turning', 'west', 'the-close-dark', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-close-ground', 'door', 'The Close Ground', 'The stand crowds in until you are turning your shoulders to get between trunks, and the canopy closes over so completely that the floor is bare, brown, and silent. Sound stops carrying. You can hear your own pulse in your ears, which means there is nothing else to hear.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-close-ground', 'east', 'the-ash-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-close-ground', 'south', 'the-turning', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-close-ground', 'west', 'the-turned-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-swallowing', 'door', 'The Swallowing', 'Ivy has come up every trunk and out along every branch until the shapes overhead are not trees any more, only a mass. The light that gets down is green and even and comes from no particular direction, so nothing casts a shadow, so nothing has a side.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swallowing', 'east', 'the-charcoal-flat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swallowing', 'north', 'the-turning', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-swallowing', 'west', 'the-hollow-beeches', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-close-dark', 'door', 'The Close Dark', 'Trunks in every direction at about the same spacing, going back into a green-brown dimness that ends wherever your eye gives up. The floor is leaf-mould, deep and soft and unmarked. There is a fallen limb here, half rotted, with a fern growing out of the split.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-close-dark', 'north', 'the-turned-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-close-dark', 'south', 'the-hollow-beeches', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-close-dark', 'east', 'the-listening-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-close-dark', 'west', 'the-same-tree', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-turned-ground', 'door', 'The Turned Ground', 'The floor has been worked over — turned, rooted through, the leaf-litter thrown up in ridges across a good stretch of ground. It was done thoroughly and it was not done recently. Beyond the worked ground the trees stand as they stand everywhere.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turned-ground', 'north', 'the-heart-of-it', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turned-ground', 'south', 'the-same-tree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turned-ground', 'east', 'the-ash-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-turned-ground', 'west', 'the-listening-stand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-same-tree', 'door', 'The Same Tree', 'A beech with a burl on it the size of a head, grey bark, one dead branch out to the left, standing among others. You have not seen this tree before. You are fairly sure you have not seen this tree before.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-same-tree', 'north', 'the-heart-of-it', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-same-tree', 'south', 'the-listening-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-same-tree', 'east', 'the-turned-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-same-tree', 'west', 'the-hollow-beeches', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-listening-stand', 'door', 'The Listening Stand', 'Somewhere close, a wood-pigeon is working through its two notes over and over, and it does not stop or move when you do. Everything else here has decided to be quiet. The trees are ordinary. The quiet is not, quite.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-listening-stand', 'north', 'the-hollow-beeches', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-listening-stand', 'south', 'the-heart-of-it', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-listening-stand', 'east', 'the-same-tree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-listening-stand', 'west', 'the-turned-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-hollow-beeches', 'door', 'The Hollow Beeches', 'Old beeches gone hollow standing on their own roots, each one a shell you could step inside if you wanted to be inside something. The ground between them is bare and pale and takes a footprint well. There are footprints. Some of them are the right size.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-beeches', 'north', 'the-same-tree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-beeches', 'south', 'the-close-dark', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-beeches', 'east', 'the-heart-of-it', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow-beeches', 'west', 'the-listening-stand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn) VALUES
  ('the-heart-of-it', 'door', 'The Heart of It', 'Nothing announces this place. The trees are the same trees, the light is the same green, the floor is the same soft depth of years of leaves — and the wood is very obviously not the same here, in a way you could not put into a sentence if you had to. Southward the ground falls away and lightens, slightly.', 0, 0, 'wood', 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heart-of-it', 'north', 'the-turned-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heart-of-it', 'south', 'the-charcoal-flat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heart-of-it', 'east', 'the-listening-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heart-of-it', 'west', 'the-same-tree', NULL);
